<template><section class="bio-nexus-panel laboratory-panel"><div class="bio-nexus-panel-heading"><div><p class="bio-nexus-panel-eyebrow">Mensajería</p><h3>Envío por correo</h3></div></div><div class="email-grid"><label class="check mode"><input v-model="model.sendEmail.isGmail" type="checkbox" :disabled="disabled"><span>El correo de envío es Gmail</span></label><template v-if="!model.sendEmail.isGmail"><BioNexusFormField label="Host" field-id="smtp-host"><input v-model="model.sendEmail.host" class="bio-nexus-field" :disabled="disabled"></BioNexusFormField><BioNexusFormField label="Puerto" field-id="smtp-port"><input v-model.number="model.sendEmail.port" class="bio-nexus-field" type="number" min="0" :disabled="disabled"></BioNexusFormField><label class="check"><input v-model="model.sendEmail.secure" type="checkbox" :disabled="disabled"><span>Usar SSL</span></label></template><BioNexusFormField label="Usuario" field-id="smtp-user"><input v-model="model.sendEmail.user" class="bio-nexus-field" autocomplete="off" :disabled="disabled"></BioNexusFormField><BioNexusFormField label="Nueva contraseña" field-id="smtp-pass" help="Déjela vacía para conservar la contraseña actual"><input v-model="model.sendEmail.pass" class="bio-nexus-field" type="password" autocomplete="new-password" :disabled="disabled"></BioNexusFormField><BioNexusFormField label="Remitente (from)" field-id="smtp-from"><input v-model="model.sendEmail.from" class="bio-nexus-field" type="email" :disabled="disabled"></BioNexusFormField></div><p class="bio-nexus-note">La contraseña SMTP nunca se muestra y solo se reemplaza al escribir una nueva.</p></section></template>
